 const show=(heading,data)=>{title.textContent=heading;body.innerHTML=data.length?data.map(e=>{const docs=e.documents||[],contracts=e.contract_histories||[],active=e.status_aktif==='aktif';return `<div class="direksi-detail-row ${active?'is-active':e.status_aktif?'is-inactive':''}"><b>${esc(e.nama)}</b><small>NIP: ${esc(e.nip)} | Divisi: ${esc(e.jabatan_divisi||e.divisi_akademik)} | Telepon: ${esc(e.telepon)}</small><small>Dokumen: ${docs.length} | Kontrak: ${contracts.length?'Tersedia':'Belum tersedia'} | Status: ${esc(e.status_aktif||'Belum diisi')}</small></div>`}).join(''):'<p class="empty">Tidak ada data.</p>';bootstrap.Modal.getOrCreateInstance(modal).show()};
 document.querySelectorAll('.direksi-dashboard .kpi').forEach(card=>card.addEventListener('click',()=>{const i=Number(card.dataset.direksiDetail.replace('kpi-',''));let d=direksiDetails||[];if(i===1)d=d.filter(e=>['pengajar','karyawan_pengajar'].includes(e.user?.role));if(i===3)d=d.filter(e=>e.status_aktif==='aktif');if(i===4)d=d.filter(e=>e.status_aktif!=='aktif');show(card.querySelector('span').textContent,d)}));
 document.querySelectorAll('.direksi-dashboard .distribution,.direksi-dashboard .bottom-card').forEach(card=>card.addEventListener('click',()=>show(card.querySelector('h5')?.textContent||'Detail',direksiDetails||[])));
})();
</script>@endpush

@push('styles')<style>
.direksi-detail-table{width:100%;border-collapse:separate;border-spacing:0;font-size:.8rem}.direksi-detail-table th{background:#f4f7fa;color:#52657d;font-weight:600;text-align:left;white-space:nowrap}.direksi-detail-table th,.direksi-detail-table td{padding:.7rem;border-bottom:1px solid #e7edf2}.direksi-detail-table tr:last-child td{border-bottom:0}.direksi-detail-table .status-active{background:#effbf3;color:#137b50}.direksi-detail-table .status-inactive{background:#fff0f1;color:#b23843}.direksi-detail-table .status-pill{display:inline-block;padding:.2rem .45rem;border-radius:999px;font-size:.7rem;font-weight:600}.direksi-detail-table-wrap{overflow-x:auto}.direksi-detail-summary{margin-bottom:.8rem;color:#728194;font-size:.8rem}
</style>@endpush
@push('scripts')<script>
(function(){
    const modal=document.getElementById('direksiDetailModal'), title=document.getElementById('direksiDetailTitle'), body=document.getElementById('direksiDetailBody');
    const employees=direksiDetails||[];
    const announcements=@json($announcements);
    const activities=@json($activities);
    const esc=v=>String(v??'-').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#039;','"':'&quot;'}[c]));
    const table=(heading,rows,announcementMode=false)=>{
        title.textContent=heading;
        if(announcementMode){body.innerHTML=rows.length?`<div class="direksi-detail-table-wrap"><table class="direksi-detail-table"><thead><tr><th>Judul</th><th>Isi</th><th>Diterbitkan</th></tr></thead><tbody>${rows.map(a=>`<tr><td>${esc(a.title)}</td><td>${esc(a.content)}</td><td>${esc(a.published_at||'Belum dipublikasikan')}</td></tr>`).join('')}</tbody></table></div>`:'<p class="empty">Tidak ada pengumuman.</p>';}
        else {body.innerHTML=rows.length?`<div class="direksi-detail-summary">Total data: ${rows.length}</div><div class="direksi-detail-table-wrap"><table class="direksi-detail-table"><thead><tr><th>Nama</th><th>NIP</th><th>Divisi</th><th>Telepon</th><th>Dokumen</th><th>Kontrak</th><th>Status</th></tr></thead><tbody>${rows.map(e=>{const active=e.status_aktif==='aktif';return `<tr><td>${esc(e.nama)}</td><td>${esc(e.nip)}</td><td>${esc(e.jabatan_divisi||e.divisi_akademik)}</td><td>${esc(e.telepon)}</td><td>${(e.documents||[]).length}</td><td>${(e.contract_histories||[]).length?'Tersedia':'Belum tersedia'}</td><td><span class="status-pill ${active?'status-active':'status-inactive'}">${esc(e.status_aktif||'Belum diisi')}</span></td></tr>`}).join('')}</tbody></table></div>`:'<p class="empty">Tidak ada data.</p>';}
        bootstrap.Modal.getOrCreateInstance(modal).show();
    };
    document.querySelectorAll('.direksi-dashboard .kpi').forEach(card=>card.addEventListener('click',()=>{
        const i=Number(card.dataset.direksiDetail.replace('kpi-',''));let rows=employees;
        if(i===1)rows=rows.filter(e=>['pengajar','karyawan_pengajar'].includes(e.user?.role));
        if(i===2)rows=rows.filter(e=>e.user?.role==='direksi');
        if(i===3)rows=rows.filter(e=>e.status_aktif==='aktif');
        if(i===4)rows=rows.filter(e=>e.status_aktif!=='aktif');
        table(card.querySelector('span').textContent,rows);
    }));
    document.querySelectorAll('.direksi-dashboard .chart-card,.direksi-dashboard .executive-card,.direksi-dashboard .distribution').forEach(card=>card.addEventListener('click',()=>{
        const heading=card.querySelector('h5')?.textContent||'Detail';let rows=employees;
        if(heading.includes('Perkembangan')){const start=new Date();start.setMonth(start.getMonth()-2);rows=rows.filter(e=>e.updated_at&&new Date(e.updated_at)>=start);}
        if(heading.includes('Aktivitas')){title.textContent=heading;body.innerHTML=activities.length?`<div class="direksi-detail-table-wrap"><table class="direksi-detail-table"><thead><tr><th>Waktu</th><th>Pengguna</th><th>Aksi</th><th>Perubahan</th></tr></thead><tbody>${activities.map(a=>`<tr><td>${esc(a.created_at)}</td><td>${esc(a.user?.name||'Sistem')}</td><td>${esc(a.action)}</td><td>${esc(a.description||'-')}</td></tr>`).join('')}</tbody></table></div>`:'<p class="empty">Belum ada aktivitas pembaruan.</p>';bootstrap.Modal.getOrCreateInstance(modal).show();return;}
        if(heading.includes('Ringkasan Eksekutif'))rows=rows.filter(e=>!e.nama||!e.email||!e.telepon||!e.alamat);
        table(heading,rows);
    }));
    document.querySelectorAll('.direksi-dashboard .bottom-card').forEach(card=>card.addEventListener('click',()=>{
        const heading=card.querySelector('h5')?.textContent||'Detail';
        if(heading.includes('Pengumuman'))table(heading,announcements,true);else table(heading,[]);
    }));
})();
</script>@endpush
